def fmea():
    out = []; n = 0; c = 0
    for code, rows in ROWS.items():
        for r in rows:
            (comp, func, mode, cause, local, effect, prev, det, S, O, D, rec, atype, owner, due, O2, D2, verify, fta) = r
            if code == "IF": c += 1; fid = f"C-{c:02d}"; grp = "연동"
            else: n += 1; fid = f"FM-{n:02d}"; grp = "본체"
            out.append({"id": fid, "grp": grp, "code": code, "ss": SS[code], "comp": comp, "func": func, "mode": mode, "cause": cause, "local": local, "effect": effect,
                        "prev": prev, "det": det, "S": S, "O": O, "D": D, "rec": rec, "atype": atype, "owner": owner, "due": due, "S2": S, "O2": O2, "D2": D2, "verify": verify, "fta": fta})
    return out
